"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[995],{8995:(e,t,a)=>{a.d(t,{B0:()=>l,R6:()=>i,iJ:()=>o,l6:()=>s,pP:()=>r,rz:()=>n});let i=["All","Business","Technology","Healthcare","Legal","Leadership","Community"],n=["All","Business","Dining & Culinary","Professional & Finance","Health & Wellness","Technology & Creative","Real Estate & Construction"],o=[{id:"art-01",slug:"black-business-journals-kid-press-corps-trains-local-tv-station",title:"Black Business Journal's Kid Press Corps Trains At Local TV Station",subtitle:"Emmy Award-winning journalist Ashley Goudeau sat down with Black Business Journal's Kid Reporters to share a few tricks of the trade.",category:"Technology",isHero:!1,isFeatured:!1,isTrending:!1,views:0,readTime:"3 min read",date:"September 15, 2026",author:{name:"Black Business Journal Editorial Team",role:"Community News Desk",avatar:"https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&w=300&q=80",bio:"The Black Business Journal Editorial Team covers stories of community leadership, education, and opportunity across Central Texas."},imageUrl:"/blog1.jpg",imageCaption:"Ashley Goudeau teaching Kid Reporters interview techniques.",excerpt:"Six Kid Reporters had the opportunity to train first hand in a local television station thanks to television news Anchor Ashley Goudeau.",pullQuote:"Research your story, write down your questions, and listen closely.",pullQuoteAuthor:"Ashley Goudeau, KVUE Midday Anchor and Political Reporter",keyTakeaways:["Research who or what your story is about.","Write down your questions.","Listen closely during your interview to ask follow-up questions."],paragraphs:["Six Kid Reporters had the opportunity to train first hand in a local television station thanks to television news Anchor Ashley Goudeau.","Goudeau said she is blessed to be a part of the KVUE news team, serving the people of Central Texas and was thrilled to share her knowledge with the young journalists.","Goudeau serves as KVUE's Midday anchor and as KVUE's political reporter. Goudeau shared that on the last day of her sophomore year of high school her history teacher told her she would be a great television news reporter. He said her versatility and ability to strike up a conversation with anyone would help make her a great journalist.","Goudeau gave the Kid Journalists valuable information on conducting live TV interviews. She told the crew of six local elementary and middle school students who are interested in TV careers the three keys to live TV interview.","The trip was sponsored by Made Media Group, a local nonprofit, whose mission is to help minority kids seek careers in media and technology.","Contact info@blackbusinessjournal.com if you have a story to share with our local journalists."],tags:["Kid Press Corps","Ashley Goudeau","KVUE","Media Careers","Youth Journalism"]},{id:"art-02",slug:"have-you-seen-gracie-missing-giraffe-texas-hill-country",title:"Have you seen Gracie, the missing giraffe in the Texas hill country?",subtitle:"Authorities are searching for a giraffe named Gracie after the animal escaped a ranch in Real County on Monday.",category:"Community",isHero:!1,isFeatured:!1,isTrending:!0,views:4210,readTime:"3 min read",date:"September 15, 2026",author:{name:"Black Business Journal Editorial Team",role:"Community News Desk",avatar:"https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&w=300&q=80",bio:"The Black Business Journal Editorial Team covers local and community stories across Central Texas and beyond."},imageUrl:"/blog2.jpg",imageCaption:"A giraffe on a Texas ranch as authorities continue the search for Gracie.",excerpt:"Authorities are searching for a giraffe named Gracie after the animal escaped a ranch in Real County, while ranch staff say she has been located and is expected to return home Tuesday.",pullQuote:"She’s a little farther away than I’d like her to be, but we’re hopeful she’ll be back home sometime Tuesday.",pullQuoteAuthor:"Vick Jones, ranch manager",keyTakeaways:["Gracie escaped from Cedar Hollow Ranch in Real County on Monday.","The ranch manager said Gracie has been located and is expected to return home Tuesday.","The ranch has kept giraffes for at least 30 years.","The animal was last seen on a game camera west of Leakey."],paragraphs:["Authorities are searching for a giraffe named Gracie after the animal escaped a ranch in Real County on Monday. The ranch manager said they have located Gracie and are hopeful she will be back home sometime Tuesday.","The ranch has had giraffes for at least 30 years, the manager said. According to a Facebook post made by the Real County Animal Rescue-Shelter, the giraffe named Gracie disappeared from the Cedar Hollow Ranch.","Gracie was last spotted on a game camera west of Leakey, according to the post. Vick Jones, who manages the ranch, told FOX Local that Gracie has been located. He’s hopeful she’ll be back at the ranch sometime Tuesday.","“She’s a little farther (away) than I’d like her to be,” Jones said, when asked where Gracie had been found. Jones said they have had giraffes at the ranch for at least 30 years. He said Gracie wandered into a part of the ranch where the giraffes hadn’t gone before and was able to get out of a gate.","The incident has drawn attention from local residents and animal welfare groups in the Texas Hill Country, where the search for the missing giraffe has become a community story. Ranch staff continue to monitor the area as they work to guide Gracie back toward the property safely."],tags:["Texas Hill Country","Real County","Missing Giraffe","Wildlife","Animal Rescue"]},{id:"art-03",slug:"austin-paid-766k-for-police-chief-exit-heres-what-happened",title:"Austin Paid $766K for a Police Chief Exit—Here’s What Happened",subtitle:"The payout to former interim police chief Robin Henderson reflects a broader nationwide challenge of recruiting top police executives, experts say.",category:"Leadership",isHero:!1,isFeatured:!1,isTrending:!0,views:0,readTime:"6 min read",date:"September 15, 2026",author:{name:"Black Business Journal Editorial Team",role:"Investigations Desk",avatar:"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=300&q=80",bio:"The Black Business Journal Editorial Team tracks civic accountability, public-sector leadership, and the cost of governance in Central Texas."},imageUrl:"/blog3.webp",imageCaption:"Former interim Austin police chief Robin Henderson during a period of transition in city leadership.",excerpt:"A departing Austin police leader received a $766,000 payout after city officials crafted an unusual compensation deal to persuade her to take over the department on an interim basis, according to records obtained by the American-Statesman.",pullQuote:"It is pretty shocking. When we talk about public service, that is usually not the most lucrative path.",pullQuoteAuthor:"City Council Member Ryan Alter",keyTakeaways:["Austin paid former interim chief Robin Henderson $766,236 in total compensation and exit-related payouts.","The package included pension-related payments, sick leave accruals, and incentives tied to leadership continuity.","Experts say the arrangement reflects a national challenge in recruiting experienced police leaders under intense public scrutiny.","The agreement drew criticism as Austin faces budget pressure and questions over public spending."],paragraphs:["A departing Austin police leader received a $766,000 payout after city officials crafted an unusual compensation deal to persuade her to take over the department on an interim basis, according to records obtained by the American-Statesman.","The January payment far exceeds what most city executives or police officers receive when they retire and has raised questions among local officials as Austin confronts budget pressure and increased scrutiny over spending.",'"It is pretty shocking," City Council Member Ryan Alter said. "When we talk about public service, that is usually not the most lucrative path."',"The agreement reflects a broader challenge facing cities nationwide: recruiting and retaining top police leaders has become more difficult in recent years, prompting some governments to offer enhanced pay, pension protections, and exit packages. In Austin, officials said the deal was designed to keep a veteran officer in place during a period of high attrition and leadership turnover — but the size and structure of the payout highlight the financial tradeoffs of those efforts.","To secure Robin Henderson's agreement to serve as interim chief in 2023, the city structured a package that supplemented her salary, protected her pension contributions and added incentives for her to remain in the role until a permanent chief was hired.","Those provisions — including pension-related payments, expanded sick leave payouts and additional compensation negotiated at the end of her tenure — ultimately brought her total payout to $766,236.","Henderson, a nearly three-decade veteran of the department, retired in January. Her payout included more than $374,000 tied to pension-related payments, about $336,000 in unused sick leave and tens of thousands of dollars in additional compensation and stipends.",'Henderson, in a written statement, defended the payout as fair and said it was an honor to serve Austin for nearly 29 years. "I appreciate the City\'s response to my unique situation and responding appropriately," she said.',"The agreement was negotiated during a period of transition at City Hall, when both the city manager and assistant city manager overseeing the police department were serving in interim roles. Officials said the arrangement did not require City Council approval because it was structured as an employment compensation matter.",'Bruce Mills, then interim assistant city manager, said the deal was intended to persuade Henderson — who was eligible to retire — to step into a role few others were positioned to fill. "We wanted to make sure she was properly compensated to serve as the interim chief, knowing this was not going to be a three month, four month job but a relatively long period of time," Mills said. "We went the extra mile to make sure she was generously compensated."',"At the time, the department was grappling with staffing shortages and leadership turnover. Henderson, who had been serving as chief of staff, had broad internal support, Mills said.","The agreement ensured that Henderson's pay would match that of the previous police chief, even though she was technically serving in an interim role. It also included additional payments to offset income she lost when a labor contract between the city and rank-and-file officers lapsed — a gap that did not apply to her position.",'"I was the only sworn member of the department under the Meet and Confer agreement facing a reduction in pay and reduction in pension contributions," she wrote in her statement.',"But the largest component of the payout stemmed from how the city handled her pension. Because portions of Henderson's compensation were structured as stipends — which are not counted toward pension contributions — the city agreed to make a lump-sum payment when she retired to account for what she otherwise would have contributed, along with projected growth over time. That payment totaled nearly $375,000.","Mills said he was surprised to learn that the agreement netted that amount for Henderson's pension. The agreement also included incentives designed to keep Henderson in the role until a permanent chief was hired.","Like other officers, she was already eligible to be paid out for up to 1,700 hours of unused sick leave — a benefit that can result in six-figure payouts for longtime employees. Henderson, who rarely took sick leave, received about $243,500 under that provision. Her interim chief agreement added up to 800 more hours of supplemental sick leave, worth roughly $92,700.","When the city hired Police Chief Lisa Davis in August 2024, officials initially planned for Henderson to transition out of the department while remaining on the payroll through January. Under that agreement, she would not have been required to report to work.","Instead, Davis asked Henderson to remain in a full-time role to help with the leadership transition, according to city officials. Davis, who earns $288,000 a year, did not negotiate an agreement like Henderson's.","Henderson stayed on for another 14 months, a period that became increasingly rocky. In a November email to Davis, she said she felt sidelined during organizational changes and expressed concern about the uncertainty surrounding her retirement timeline.",'"I would hope and appreciate this process being handled with dignity and respect," she wrote. Henderson also raised concerns about additional compensation not detailed in earlier agreements. Those discussions led to a December deal in which the city agreed to pay her $55,000 in exchange for releasing any potential legal claims.',"Current Deputy City Manager Jon Fortune said he honored the existing agreements when issuing Henderson's final payout earlier this year.","City officials said Henderson's payout was funded through the police department's budget, using money set aside for contractual obligations such as sick leave payouts, and did not affect operations.","Still, the payment comes as Austin leaders face mounting pressure to rein in spending amid a serious budget crunch and revelations that some officials had expensed solo meals, upgraded flights and other questionable items. Earlier this year, the City Council approved an outside audit aimed at identifying cuts and restoring public trust.",'"Clearly, Robin dedicated her career to the city, and we should properly value that," Alter, the council member, said. "It is also a little bit frustrating that when we are always told that there is no money, and there are no cuts that the police department can make, that they were able to find hundreds of thousands of dollars for this purpose."',"Experts say such agreements, while uncommon, are becoming more prevalent as cities compete for a limited pool of experienced police leaders. \"We saw 2020 was the year of 'defund the police,' but in the years after that, it has been 'pay the police,'\" said Ian Adams, a criminology professor at the University of South Carolina and former police labor leader.",'"The people qualified to run our largest public policing organizations — this is not a widely distributed skill set," Adams said. Gene Ellis, executive director of the Texas Police Chiefs Association, said some chiefs now negotiate severance protections or guaranteed compensation before taking top jobs because of the political volatility of the role.','"You are in a position that is under a lot of pressure, a lot of scrutiny," he said. Both declined to comment directly on Henderson\'s agreement, though Adams noted that compensation for public officials should be subject to public scrutiny.','Austin Human Resources Director Susan Sinz, who was hired two years ago and has worked in municipal government for decades, described agreements like Henderson\'s as "super exceptional." "It has to be for a very specific set of circumstances," she said. "It just doesn\'t happen that often."','Henderson, in her statement, said she planned to continue serving the community during her retirement. "It was an honor and privilege to work for the City and serve our Austin community for almost 29 years as an Austin police officer," she said. "In my retirement, I will remain active to make a positive contribution to our Austin community."'],tags:["Austin Police","Robin Henderson","Police Leadership","Public Spending","City Budget"]},{id:"art-04",slug:"austin-black-business-journal-launches-community-health-wellness-initiative",title:"Austin Black Business Journal Launches Community Health & Wellness Initiative, Invites Public Engagement",subtitle:"Join us as we Elevate Health & Wellness. Strengthen the Black Communities.",category:"Healthcare",isHero:!1,isFeatured:!1,isTrending:!0,views:0,readTime:"5 min read",date:"September 15, 2026",author:{name:"Black Business Journal Editorial Team",role:"Community Health Desk",avatar:"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=300&q=80",bio:"The Black Business Journal Editorial Team covers community health, wellness, and public engagement across Central Texas."},imageUrl:"/blog4.png",imageCaption:"ABBJ is inviting the community to participate in its new Health & Wellness Initiative through listening sessions, subscriptions, and public engagement.",excerpt:"The Austin Black Business Journal & Community News Magazine is calling on the community to help shape a new health-focused media initiative designed to elevate Black voices, concerns, and lived experiences across Central Texas.",pullQuote:"We believe the most powerful stories come directly from the community. This initiative is about more than reporting—it’s about listening, engaging, and ensuring that our coverage reflects real needs, real barriers, and real solutions.",pullQuoteAuthor:"ABBJ Leadership",keyTakeaways:["ABBJ launched a Health & Wellness Initiative focused on mental health, chronic disease, preventive care, and social determinants of health.","The effort aims to reach more than 120,000 readers in the next two years.","Residents can subscribe, request a free copy of the upcoming issue, share health concerns, and submit story ideas.","The initiative includes listening sessions, health summits, volunteer opportunities, and print distribution support for seniors and digitally underserved residents."],paragraphs:["The Austin Black Business Journal & Community News Magazine (ABBJ) is calling on the community to help shape a new, health-focused media initiative designed to elevate the voices, concerns, and lived experiences of Black residents across Central Texas.","As part of its expanded commitment to community-centered journalism, ABBJ has launched a Health & Wellness Initiative that will focus on critical issues including mental health, chronic disease, preventive care, and the social determinants of health. The initiative is expected to reach over 120,000 readers within the next two years, providing culturally relevant and accessible information to communities that are often underserved by traditional media.","At the heart of this effort is a newly released community engagement form, which invites residents to not only subscribe to the publication, but also actively participate in shaping its editorial direction.","“We believe the most powerful stories come directly from the community,” said ABBJ leadership. “This initiative is about more than reporting—it’s about listening, engaging, and ensuring that our coverage reflects real needs, real barriers, and real solutions.”","Through the form, community members can subscribe to ABBJ in print or digital format, request a free copy of the upcoming Health & Wellness Issue, share insights on the most pressing health and social issues affecting their communities, and submit story ideas or express interest in contributing content.","In addition to content contributions, ABBJ is expanding its community presence through listening sessions, health summits, and resource events. Residents can sign up to attend, volunteer, or even partner and sponsor these efforts.","A key focus of the initiative is accessibility. ABBJ is also seeking volunteers to assist with monthly print distribution, ensuring that seniors and individuals with limited digital access can still receive trusted health information.","This approach reflects a broader shift in local media—one that prioritizes community voice, equity, and direct engagement as essential components of effective journalism.","Residents interested in participating are encouraged to scan the official ABBJ QR code to access the form, subscribe, and get involved.","As ABBJ continues to expand its reach and impact, this initiative signals a clear goal: to inform, empower, and uplift the health of Black communities across Central Texas—together."],tags:["Health & Wellness","Community Health","Black Communities","Public Engagement","ABBJ"]},{id:"art-05",slug:"creative-tech-mentorship-program-art-curatorial-inc",title:"Introducing the Creative Mentorship Program",subtitle:"Art Curatorial Inc. launches a six-week Creative Tech Mentorship Program for Austin creatives from under-resourced communities.",category:"Technology",isHero:!1,isFeatured:!0,isTrending:!0,views:0,readTime:"3 min read",date:"September 18, 2026",author:{name:"Black Business Journal Editorial Team",role:"Technology & Community News Desk",avatar:"https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&w=300&q=80",bio:"The Black Business Journal Editorial Team covers creative careers, technology, education, and opportunity across Central Texas."},imageUrl:"/blog5.jpg",imageCaption:"Creative technology mentorship supporting Austin storytellers, designers, and digital creatives.",excerpt:"Art Curatorial Inc. is introducing a six-week Creative Tech Mentorship Program supporting three Austin creatives from under-resourced communities with mentorship, tools, project experience, and career pathways.",pullQuote:"Art should not just be created; it should be a foundation for economic stability and cultural continuity.",pullQuoteAuthor:"Art Curatorial Inc.",keyTakeaways:["The six-week program will support three creatives from under-resourced Austin communities.","Mentees will receive one-on-one mentorship from Austin technology and creative industry leaders.","Participants will receive Adobe Creative Suite access and real-world project experience.","Applications are available at https://www.artcuratorialinc.org/mentorship."],paragraphs:["Introducing the Creative Mentorship Program, brought to you by Art Curatorial Inc. at https://www.artcuratorialinc.org/.","The organization is launching a Creative Tech Mentorship Program, a six-week initiative supporting three creatives from under-resourced communities in Austin who have a passion for storytelling, design, or digital creativity and a commitment to making a positive impact in their communities.","Mentees will receive one-on-one mentorship with Austin technology and creative industry leaders, full access to the Adobe Creative Suite, and real-world project experience they can use immediately.","The program will also help participants build a professional portfolio, identify clear career pathways in digital media, and expand their network of industry professionals.","Art Curatorial Inc. is a 501(c)(3) nonprofit dedicated to expanding creative opportunities and building sustainable futures for artists of color. The organization centers mentorship, entrepreneurship, and career pathways because art can be a foundation for economic stability and cultural continuity.","Creatives ready to take the next step can apply now at https://www.artcuratorialinc.org/mentorship."],tags:["Creative Mentorship","Creative Technology","Digital Media","Austin Creatives","Art Curatorial Inc."]},{id:"art-06",slug:"2026-austin-black-business-journal-honors-nominations-open",title:"Nominations Are Now Open: 2026 Austin Black Business Journal Honors Black Excellence",subtitle:"The 2026 Austin Black Business Journal Awards are accepting nominations for individuals, businesses, organizations, and nonprofits making a meaningful impact across Central Texas.",category:"Leadership",isHero:!1,isFeatured:!0,isTrending:!0,views:0,readTime:"4 min read",date:"September 18, 2026",author:{name:"Black Business Journal Editorial Team",role:"Leadership & Community News Desk",avatar:"https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&w=300&q=80",bio:"The Black Business Journal Editorial Team celebrates leadership, service, and Black excellence across Central Texas."},imageUrl:"/blog6.png",imageCaption:"The 2026 Austin Black Business Journal Honors invite nominations celebrating Black excellence across Central Texas.",excerpt:"Nominations are open for the 2026 Austin Black Business Journal & Community News Magazine Awards, recognizing individuals, businesses, organizations, and nonprofits whose work strengthens Central Texas.",pullQuote:"Recognition has power. It builds momentum, pride, and community.",pullQuoteAuthor:"Austin Black Business Journal",keyTakeaways:["Nominations are open for the 2026 Austin Black Business Journal Honors.","Individuals, businesses, organizations, and nonprofits may be nominated.","Nominations close in March 2026 and selected nominees will be honored at the 2026 Awards Reception.","Submit a nomination at https://form.jotform.com/240075088791159."],paragraphs:["The 2026 Austin Black Business Journal & Community News Magazine Awards nominations are officially open, inviting the Central Texas community to shine a light on Black excellence.","The awards celebrate everyday heroes, leaders, innovators, and change-makers whose work improves their communities, often behind the scenes. Individuals, businesses, organizations, and nonprofits whose work uplifts others and strengthens Central Texas are eligible.","Nominating someone brings attention to good deeds and leadership, inspires others across the region to serve and lead, encourages nominees to expand their work, and publicly affirms that their efforts matter.","After nominations close, a qualified review team will evaluate submissions using established criteria. Selected nominees will be honored at the 2026 Awards Reception, where excellence across industries and service areas will be celebrated.","To submit a nomination, complete the online form at https://form.jotform.com/240075088791159 before the March 2026 deadline. Be specific and share clear examples explaining why your nominee deserves recognition.","Nominations are being accepted for Black Professionals & Entrepreneurs, Black Lawyers, Most Influential Black Men & Women, Black Doctors, Diversity & Inclusion Champions, Blacks in Tech / Millennials, Blacks in Education, Black-Owned Nonprofits, and 40 Under 40 Business Awards."],tags:["Black Excellence","Awards","Leadership","Community Recognition","Austin Honors"]},{id:"art-07",slug:"austin-spurs-host-black-heritage-night",title:"Austin Spurs Host Black Heritage Night",subtitle:"The Austin Spurs invite Central Texas community leaders, organizations, creatives, and families to celebrate Black Heritage Night at H-E-B Center at Cedar Park.",category:"Community",isHero:!1,isFeatured:!0,isTrending:!0,views:0,readTime:"3 min read",date:"September 18, 2026",author:{name:"Black Business Journal Editorial Team",role:"Community News Desk",avatar:"https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&w=300&q=80",bio:"The Black Business Journal Editorial Team covers community events, culture, education, and opportunity across Central Texas."},imageUrl:"/blog7.jpeg",imageCaption:"Austin Spurs Black Heritage Night brings community, culture, and connection together at H-E-B Center at Cedar Park.",excerpt:"The Austin Spurs will host Black Heritage Night with a pregame sneaker summit, local vendors, and support for Huston-Tillotson University Athletics.",pullQuote:"Black Heritage Night is more than a game—it is a gathering rooted in appreciation for the diverse community that makes Central Texas thrive.",pullQuoteAuthor:"Austin Spurs",keyTakeaways:["Black Heritage Night takes place Thursday, January 29 at 7:00 PM at H-E-B Center at Cedar Park.","Doors open at 6:00 PM for the Pregame Sneaker Summit and vendor experience.","More than a dozen sneaker and clothing vendors will be featured on the concourse.","A portion of select ticket sales will benefit Huston-Tillotson University Athletics."],paragraphs:["The Austin Black Business Journal & Community News Magazine is proud to share an invitation from the Austin Spurs as they kick off Black History Month with Black Heritage Night.","On Thursday, January 29 at 7:00 PM, the Austin Spurs will host the celebration at H-E-B Center at Cedar Park, bringing together community leaders, organizations, creatives, and families from across Central Texas.","The evening will feature a Pregame Sneaker Summit presented in partnership with Kicking It, an Austin-based business championing sneaker culture and entrepreneurship. More than a dozen sneaker and clothing vendors will be showcased on the concourse, and doors open at 6:00 PM so guests can explore before tipoff.","A portion of select ticket sales from Black Heritage Night will directly benefit Huston-Tillotson University Athletics, helping support student-athletes and higher education opportunities within the community.","Community partners are encouraged to share the complimentary ticket link at https://www.gofevo.com/event/20thanniversarycomm20251023-112837015 with staff, board members, donors, volunteers, community members, and families.","As the community reflects during MLK Jr. weekend, Black Heritage Night offers a meaningful continuation of culture, creativity, and collective progress. For event details, visit https://austin.gleague.nba.com/community-nights."],tags:["Austin Spurs","Black Heritage Night","Black History Month","Huston-Tillotson University","Community Events"]},{id:"art-08",slug:"remembering-tommie-lee-t-l-wyatt-legend-of-black-austin",title:"Remembering Tommie Lee (T. L.) Wyatt: A Mentor, a Messenger, and a Legend of Black Austin",subtitle:"T. L. Wyatt leaves a lasting legacy as a publisher, civic leader, mentor, and steadfast voice for Austin’s Black community.",category:"Community",isHero:!1,isFeatured:!0,isTrending:!0,views:0,readTime:"6 min read",date:"September 18, 2026",author:{name:"Black Business Journal Editorial Team",role:"History & Community News Desk",avatar:"https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&w=300&q=80",bio:"The Black Business Journal Editorial Team preserves and shares the stories, leaders, and institutions that shaped Black Austin."},imageUrl:"/blog8.jpg",imageGallery:["/blog8(i).jpg","/blog8(ii).jpg","/blog8(iii).jpg"],imageCaption:"Tommie Lee (T. L.) Wyatt, a mentor, messenger, and legend of Black Austin.",excerpt:"Tommie Lee (T. L.) Wyatt, a steadfast voice for Austin’s Black community and a champion of truthful, empowering journalism, passed away peacefully at 88.",pullQuote:"The community needed a voice.",pullQuoteAuthor:"Tommie Lee (T. L.) Wyatt",keyTakeaways:["T. L. Wyatt passed away peacefully on January 9, 2026, at age 88.","He co-founded The Villager newspaper in 1973 to tell the positive, truthful stories of Black Austin.","Wyatt served as a civic leader on boards and commissions across Austin and Texas.","His legacy continues through the journalists, institutions, and young people he mentored."],paragraphs:["Tommie Lee (T. L.) Wyatt, a steadfast voice for Austin’s Black community and a lifelong champion of truthful, empowering journalism, passed away peacefully in his sleep on January 9, 2026, at the AVIR at Park Bend facility in Austin, Texas. He was 88 years old and was in the presence of his son, Thomas L. Wyatt.","Born on July 27, 1937, in Point Blank, Texas, Wyatt earned a football scholarship and graduated from Bishop College in Marshall, Texas, with a bachelor’s degree in Business Administration. His early life was shaped by discipline, determination, and a belief in possibility.","In 1962, Wyatt moved to Austin, entering a city still constrained by segregation. He remembered East Austin for its brilliance: a vibrant, self-sustaining Black community filled with thriving businesses, cultural pride, and deep-rooted connections.","In 1973, Wyatt, his wife Barbara, and a close friend co-founded The Villager newspaper with a bold mission: to tell the positive, truthful stories of Black Austin. When his co-founders moved on, Wyatt carried the paper forward and insisted that Black communities deserved coverage reflecting their full humanity.","Wyatt often said, “The community needed a voice.” Through The Villager, his magazine Loquacity, and KAZI, Austin’s only Black radio station at the time, he answered that call. He understood the importance of Black newspapers as places of accessibility, memory, and belonging.","Beyond journalism, Wyatt served on the Private Industry Council, the Austin Cable Commission, and the East 11th Street Village Association. He was a founding member of the Texas Publishers Association and a steadfast member of the National Newspaper Publishers Association. Through the Youth Brigade and relationships with major corporations, he helped bring education, opportunity, and financial resources into the community.","To those who knew him, T. L. Wyatt was more than a publisher or civic leader. He was a mentor, connector, and joyful presence who built relationships through warmth, curiosity, and optimism. His vision, persistence, and love for East Austin created a legacy that will continue to guide generations.","Tommie Lee Wyatt is survived by his son, granddaughter, and great-grandchildren. Visitation will be held at Cook-Walden/Capital Parks Funeral Home on January 20, 2026, from 4:00 p.m. to 8:00 p.m. Funeral services will take place at the same location on January 21, 2026, from 10:00 a.m. to 11:00 a.m., followed by committal services at Cook-Walden Capital Parks Cemetery."],tags:["T. L. Wyatt","Black Austin History","The Villager","Journalism","Community Leadership"]},{id:"art-09",slug:"black-political-leadership-austin-metro",title:"Black Political Leadership in the Austin Metro",subtitle:"From Reconstruction-era civic pioneers to today’s elected officials, Black leaders continue shaping governance and public life across Central Texas.",category:"Leadership",isHero:!1,isFeatured:!0,isTrending:!0,views:0,readTime:"5 min read",date:"December 31, 2025",author:{name:"Black Business Journal",role:"Politics & Civic Leadership Desk",avatar:"https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&w=300&q=80",bio:"The Black Business Journal chronicles civic leadership, public policy, and the people shaping Black Austin."},imageUrl:"/blog9.png",imageGallery:["/blog9(i).jpeg","/blog9(ii).jpeg","/blog9(iii).jpg","/blog9(iv).webp","/blog9(v).jpeg"],imageCaption:"Black political leaders and civic figures who have shaped the Austin metropolitan area.",excerpt:"Black political leadership in Austin and the surrounding region has deep roots, from Reconstruction-era pioneers to current city, county, and state officials shaping Central Texas.",pullQuote:"Continued grassroots organizing, voter education, and candidate outreach are critical to translating community interests into electoral influence.",pullQuoteAuthor:"Black Business Journal",keyTakeaways:["Henry Green Madison was Austin’s first African-American elected official, serving during Reconstruction.","Wilhelmina Ruth Delco and Berl L. Handcox helped establish historic Black representation in Austin public life.","Current and emerging leaders include Sheryl Cole, Rudy Metayer, Venton Jones, and Ishmael Harris.","Voter education, grassroots organizing, and candidate outreach remain essential to civic participation."],paragraphs:["Black political leadership in Austin and the broader region has deep roots, stretching back to Reconstruction. Henry Green Madison, appointed alderman in the 1870s, was the city’s first African-American elected official and represented a pivotal early step in civic participation and leadership.","Throughout the latter twentieth century, Black leaders made historic gains. Wilhelmina Ruth Delco became the first African-American elected to public office in Austin as a school board trustee in 1968 and later served multiple terms in the Texas House of Representatives. Berl L. Handcox became the first Black person elected to the Austin City Council in 1971.","Today, Black elected officials continue shaping local and regional governance. Sheryl Cole serves as the state representative for Texas House District 46. Rudy Metayer is an elected official on the Pflugerville City Council, representing one of the Austin metro’s rapidly growing suburbs.","Venton Jones, a state representative in the Texas Legislature, has become a notable figure for LGBTQ+ and civil rights advocacy. Ishmael Harris was elected mayor of Bastrop, becoming the first Black person to hold that office and highlighting the expansion of Black political leadership beyond central Austin.","Black leaders with broader influence also shape the state’s political landscape. Congresswoman Jasmine Crockett, who represents parts of the Dallas-Fort Worth area, is a nationally recognized Black woman in public life and is running for U.S. Senate in 2026.","Black voter turnout and engagement in the Austin metro reflect a broader dynamic: Black voters are a powerful force when mobilized, while turnout in local and off-cycle races often lags behind its potential. Grassroots organizing, voter education, and candidate outreach are critical to translating community interests into electoral influence.","The rise of Black political leaders—from city council to the state legislature and national campaigns—points to a growing diversity of voices shaping policy, governance, and civic engagement in Central Texas. These leaders champion broader coalitions focused on equity, access, and representation."],tags:["Austin Politics","Black Political Leadership","Henry Green Madison","Wilhelmina Delco","Civic Engagement","Austin Metro"]},{id:"art-10",slug:"black-voter-turnout-engagement-austin-metro",title:"Black Voter Turnout and Engagement in the Austin Metro",subtitle:"Participation trends, targeted organizing, and the continuing work of building civic power among Black voters in Central Texas.",category:"Leadership",isHero:!1,isFeatured:!0,isTrending:!0,views:0,readTime:"4 min read",date:"September 18, 2026",author:{name:"Black Business Journal",role:"Politics & Civic Engagement Desk",avatar:"https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&w=300&q=80",bio:"The Black Business Journal covers voting, public policy, civic participation, and community power across Central Texas."},imageUrl:"/blog10.jpg",imageCaption:"Community members participating in civic engagement and voter outreach across the Austin metro.",excerpt:"Black voters remain a crucial part of the Texas electoral landscape, while turnout trends and targeted organizing efforts continue shaping civic participation in the Austin metro.",pullQuote:"Strategic outreach in historically under-engaged neighborhoods can increase vote rates, elevate community priorities, and support representative leadership.",pullQuoteAuthor:"Black Business Journal",keyTakeaways:["Black voters have represented roughly 11–12% of the electorate in recent statewide elections.","Turnout varies significantly by election type, with local and off-cycle elections often drawing fewer voters.","BlackTOP has led large-scale Black voter engagement efforts across Texas.","Voter education, organizing, and candidate outreach remain essential to strengthening civic participation."],paragraphs:["Black voter turnout in Texas, and specifically in local contexts like the Austin metro, has historically been lower than white voter turnout, though Black voters remain a crucial part of the electoral landscape. In recent statewide elections, Black voters comprised roughly 11–12% of the electorate and supported Democratic candidates at high rates when they turned out to vote.","In Travis County, which includes Austin, overall turnout varies substantially by election type. In the 2025 constitutional amendment election, about 25% of registered voters in Travis County cast ballots, significantly higher than the statewide average of about 16% that year.","Local turnout, especially in off-cycle or special elections, has often been lower, sometimes in the low double digits. These patterns underscore how many Austin voters do not participate unless a race is highly visible or competitive.","Community organizations have played a central role in boosting participation among Black voters across Texas, including in the Austin metro. BlackTOP, the Black Texas Organizing Project, launched one of the largest focused Black voter engagement initiatives in the state. During the 2022 elections, BlackTOP reached nearly two-thirds of Black voters in Texas through large-scale door-knocking and targeted outreach.","Efforts like these show how strategic organizing in historically under-engaged neighborhoods can increase vote rates, elevate community priorities, and support the election of leaders reflective of those communities.","Despite these mobilization efforts, structural and political factors continue to suppress turnout. Restrictive voting laws, limited eligibility for mail-in voting, redistricting, and legislative changes remain central concerns for activists working to expand access and participation."],tags:["Black Voters","Austin Elections","Voter Turnout","BlackTOP","Civic Engagement","Voting Rights"]},{id:"art-11",slug:"austin-public-library-welcomes-hannah-terrell-director-libraries",title:"Austin Public Library Welcomes Hannah Terrell as Director of Libraries",subtitle:"Hannah Terrell steps into the permanent role after serving as Interim Director and guiding Austin Public Library through a period of transition and growth.",category:"Community",isHero:!1,isFeatured:!0,isTrending:!0,views:0,readTime:"3 min read",date:"September 18, 2026",author:{name:"Black Business Journal Editorial Team",role:"Community News Desk",avatar:"https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&w=300&q=80",bio:"The Black Business Journal Editorial Team covers civic institutions, education, culture, and community leadership across Central Texas."},imageUrl:"/blog11.jpg",imageCaption:"Hannah Terrell appointed Director of Libraries for Austin Public Library.",excerpt:"Austin Public Library has appointed Hannah Terrell as its permanent Director of Libraries as the system prepares to celebrate its centennial in 2026.",pullQuote:"I look forward to continuing this work alongside the brilliant staff at APL as we move confidently together into APL’s second century of service.",pullQuoteAuthor:"Hannah Terrell, Director of Libraries",keyTakeaways:["Hannah Terrell became Austin Public Library’s permanent Director of Libraries effective December 15, 2025.","She previously served as Interim Director after Roosevelt Weeks accepted a role with Fort Bend County Libraries.","Terrell oversees more than 460 employees and the library system’s services, programs, facilities, and staff.","Austin Public Library will celebrate its centennial in 2026."],paragraphs:["Austin Public Library is pleased to announce the appointment of Hannah Terrell as its new Director of Libraries, effective December 15, 2025.","The Director of Libraries leads the Austin Public Library system, overseeing operations, programs, facilities, and staff in service to one of the nation’s fastest-growing and most diverse cities. The position became vacant when former Director Roosevelt Weeks accepted the role of Director of Fort Bend County Libraries. Terrell had served as Interim Director during the transition.","Following a nationwide search and comprehensive interview process, the City of Austin selected Terrell to assume the role on a permanent basis. She said it had been an honor to lead APL as Interim Director and expressed gratitude for the opportunity to continue the work with the library’s staff.","The appointment comes as Austin Public Library prepares to celebrate a major milestone: its centennial in 2026, marking 100 years of public service, learning, and community connection.","Terrell is a seasoned public library executive with more than 20 years of experience leading library services in large urban systems and rural communities. Since September 2024, she has overseen more than 460 employees and advanced the library’s strategic vision for Austin’s rapid growth and evolving community needs.","Her leadership is grounded in equity, collaboration, and staff development. Before joining APL, Terrell held leadership roles with Charlotte Mecklenburg Library and Union County Public Library in Charlotte, North Carolina, where she led civic engagement initiatives and service pilots designed to reach underserved communities.","Terrell holds a Master of Library Science degree from North Carolina Central University and a Bachelor of Science in Health Care Administration from the University of Detroit Mercy. Her permanent appointment continues Austin Public Library’s commitment to visionary leadership, inclusive service, and community-centered innovation."],tags:["Austin Public Library","Hannah Terrell","Community Leadership","Public Libraries","Austin Centennial"]}];o.sort((e,t)=>e.isHero!==t.isHero?e.isHero?-1:1:new Date(t.date)-new Date(e.date));let r=o.filter(e=>"Business"===e.category).map(e=>({id:e.id,name:e.title,category:"Business",owner:e.author.name,address:"Central Texas",neighborhood:"Central Texas",phone:"",description:e.excerpt,imageUrl:e.imageUrl,tags:e.tags,articleUrl:"/blog/".concat(e.slug)}));function s(e){return o.find(t=>t.slug===e)}function l(e){let t=arguments.length>1&&void 0!==arguments[1]?arguments[1]:3,a=s(e);return a?o.filter(t=>t.slug!==e&&t.category===a.category).slice(0,t):o.slice(0,t)}}}]);